    # Flood-fill background zeros reachable from the edge.
    outside = set()
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                stack.append((nr, nc))

    enclosed = {
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] == 0 and (r, c) not in outside
