                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if borders_interior:
                selected.update(comp)

    out = [row[:] for row in grid]

    # Color the interior one-cell band 3, leaving deeper interior cells alone.
    for r, c in enclosed:
        if any((r + dr, c + dc) in selected
               for dr in (-1, 0, 1) for dc in (-1, 0, 1)):
